import * as z from 'zod'

const stringArrayOrWildcard = z.union([z.literal('*'), z.array(z.string())])

/** New flat scope-first schema (current) */
const scopeConfigSchema = z
    .object({
        tables: stringArrayOrWildcard.optional(),
        roles: stringArrayOrWildcard.optional(),
    })
    .catchall(stringArrayOrWildcard)

const flatDependenciesSchema = z.record(z.string(), scopeConfigSchema)

/** Old schema with 'applications' wrapper (deprecated, tables only) */
const oldScopeConfigSchema = z.object({
    tables: z.array(z.string()).optional(),
})

const oldDependenciesSchema = z.object({
    applications: z.record(z.string(), oldScopeConfigSchema),
})

/** Combined schema supporting both old and new formats */
export const dependenciesSchema = z.union([oldDependenciesSchema, flatDependenciesSchema]).optional()

/**
 * Dependencies configuration organized by scope, then by type.
 *
 * @example
 * ```json
 * {
 *   "global": {
 *     "tables": ["cmdb_ci_server", "incident"],
 *     "roles": ["admin", "action_designer"],
 *     "sys_ui_view": ["7966be310a0a0b8c00bd504090503227"]
 *   },
 *   "sn_ace": {
 *     "tables": ["sn_ace_app_config"]
 *   },
 *   "x_example_app": {
 *     "roles": ["x_example_app.cool"],
 *     "automation.actions": "*"
 *   }
 * }
 * ```
 */
export type DependenciesConfig = z.output<typeof dependenciesSchema>
